    function secao(marca) {
        var p = String(marca).split('.');
        var c = CAPITULOS[parseInt(p[0], 10) - 1];
        if (!c) return null;
        var s = c.secoes[parseInt(p[1], 10) - 1];
        if (!s) return null;
        return { cap: c, secao: s, marca: marca, titulo: c.titulo };
    }

